CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261113233234_Inicial') THEN
    CREATE TABLE "Alimentos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(200) NOT NULL,
        "Grupo" character varying(120) NOT NULL,
        "Calorias100g" double precision NOT NULL,
        "Proteina100g" double precision NOT NULL,
        "Carboidrato100g" double precision NOT NULL,
        "Gordura100g" double precision NOT NULL,
        "Fibra100g" double precision NOT NULL,
        "Fonte" character varying(40) NOT NULL DEFAULT 'TACO',
        CONSTRAINT "PK_Alimentos" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

